// @vitest-environment node

/**
 * The renderer's copy of the compiled-in private set must equal the set the
 * daemon enforces (`crates/biorouter/src/privacy/registry_private.rs`,
 * generated by `landing/scripts/build-registry.mjs`).
 *
 * Nothing pinned the two before, and they had drifted: the mirror lacked
 * `gptragent`, so Settings badged gptr Agent Public while every gate refused it
 * to a public model. After the 2026-11-28 rename it would also have badged the
 * new id, `gptr`, Public. Read off the generated file rather than restated here,
 * so the next change to the set fails this test until the mirror follows.
 */
import { describe, expect, it } from 'vitest';
import * as fs from 'fs';
import { PRIVATE_EXTENSION_KEYS, classifyExtension } from './extensionPrivacy';
import { EXTENSION_RENAMES } from '../../../utils/extensionRenames';

const GENERATED = new URL(
  '../../../../../../crates/biorouter/src/privacy/registry_private.rs',
  import.meta.url
);

/** The string literals of `PRIVATE_EXTENSIONS` in the generated Rust file. */
function compiledPrivateSet(): string[] {
  const source = fs.readFileSync(GENERATED, 'utf8');
  const declaration = /pub const PRIVATE_EXTENSIONS: &\[&str\] =\s*&\[([^\]]*)\];/.exec(source);
  expect(declaration, 'PRIVATE_EXTENSIONS must still be one slice literal').not.toBeNull();
  return [...declaration![1].matchAll(/"([^"]*)"/g)].map((m) => m[1]);
}

describe('the desktop private set', () => {
  it('equals the set the daemon compiles in', () => {
    const compiled = compiledPrivateSet();
    expect(compiled.length, 'the generated set must not read as empty').toBeGreaterThan(0);
    expect([...PRIVATE_EXTENSION_KEYS]).toEqual(compiled);
  });

  it('is exactly the four keys the operator named, both ids of gptr Agent included', () => {
    expect([...PRIVATE_EXTENSION_KEYS]).toEqual(['cdwagent', 'gptr', 'gptragent', 'ucsfomopagent']);
  });

  it('badges a renamed private extension Private under either of its ids', () => {
    for (const { from, to } of EXTENSION_RENAMES) {
      expect(classifyExtension(from), from).toBe(classifyExtension(to));
    }
    expect(classifyExtension('gptr')).toBe('private');
    expect(classifyExtension('gptragent')).toBe('private');
    expect(classifyExtension(' GptrAgent ')).toBe('private');
  });
});
